              AND enquiry.status = "confirm"
        ) > 1 THEN "queries-converted"
        WHEN (
            SELECT COUNT(*) 
            FROM enquiry 
            WHERE enquiry.company_id = company.company_id 
              AND enquiry.status = "confirm"
        ) = 1 THEN "only-one-query-converted"
        WHEN EXISTS (
            SELECT 1 
            FROM enquiry 
            WHERE enquiry.company_id = company.company_id 
              AND enquiry.status != "confirm"
        ) THEN "query-received-but-not-converted"
        ELSE "no-query"
    END) as enquiry_status
FROM `company_details`
LEFT JOIN `company` ON `company`.`company_id` = `company_details`.`company`
WHERE `company`.`is_deleted` != '1'
AND `company_details`.`status` = 'active'
GROUP BY `company_details`.`company`
ORDER BY `company_details`.`company_id` DESC) AS t
